"use strict";

/* -------------------------------------------------------------------------- *
 * Millisecond constants (same values as in the original bundle)              *
 * -------------------------------------------------------------------------- */
const s = 1e3;          // seconds
const m = s * 60;       // minutes
const h = m * 60;       // hours
const d = h * 24;       // days
const w = d * 7;        // weeks
const y = d * 365.25;   // years (approx)

/* -------------------------------------------------------------------------- *
 * Parse a human‑readable duration string into milliseconds.                  *
 * Returns `undefined` for invalid input or strings longer than 100 chars.   *
 * -------------------------------------------------------------------------- */
function parse(str) {
  str = String(str);
  if (str.length > 100) {
    return;
  }

  const match = /^(-?(?:\d+)?\.?\d+) *(milliseconds?|msecs?|ms|seconds?|secs?|s|minutes?|mins?|m|hours?|hrs?|h|days?|d|weeks?|w|years?|yrs?|y)?$/i.exec(str);
  if (!match) {
    return;
  }

  const n = parseFloat(match[1]);
  const type = (match[2] || "ms").toLowerCase();

  switch (type) {
    case "years":
    case "year":
    case "yrs":
    case "yr":
    case "y":
      return n * y;
    case "weeks":
    case "week":
    case "w":
      return n * w;
    case "days":
    case "day":
    case "d":
      return n * d;
    case "hours":
    case "hour":
    case "hrs":
    case "hr":
    case "h":
      return n * h;
    case "minutes":
    case "minute":
    case "mins":
    case "min":
    case "m":
      return n * m;
    case "seconds":
    case "second":
    case "secs":
    case "sec":
    case "s":
      return n * s;
    case "milliseconds":
    case "millisecond":
    case "msecs":
    case "msec":
    case "ms":
      return n;
    default:
      return undefined;
  }
}

/* -------------------------------------------------------------------------- *
 * Short formatting – e.g. "2h", "5m", "10ms".                                 *
 * -------------------------------------------------------------------------- */
function fmtShort(ms) {
  const msAbs = Math.abs(ms);
  if (msAbs >= d) return Math.round(ms / d) + "d";
  if (msAbs >= h) return Math.round(ms / h) + "h";
  if (msAbs >= m) return Math.round(ms / m) + "m";
  if (msAbs >= s) return Math.round(ms / s) + "s";
  return ms + "ms";
}

/* -------------------------------------------------------------------------- *
 * Long formatting – e.g. "2 days", "5 minutes", "10 milliseconds".          *
 * -------------------------------------------------------------------------- */
function fmtLong(ms) {
  const msAbs = Math.abs(ms);
  if (msAbs >= d) return plural(ms, msAbs, d, "day");
  if (msAbs >= h) return plural(ms, msAbs, h, "hour");
  if (msAbs >= m) return plural(ms, msAbs, m, "minute");
  if (msAbs >= s) return plural(ms, msAbs, s, "second");
  return ms + " ms";
}

/* -------------------------------------------------------------------------- *
 * Helper for `fmtLong` – decides whether to pluralise the unit name.         *
 * -------------------------------------------------------------------------- */
function plural(ms, msAbs, n, name) {
  const isPlural = msAbs >= n * 1.5;
  return Math.round(ms / n) + " " + name + (isPlural ? "s" : "");
}

/* -------------------------------------------------------------------------- *
 * Main exported function.                                                    *
 *   * If `val` is a non‑empty string → parse it.                               *
 *   * If `val` is a finite number   → format it (short or long).              *
 *   * Otherwise throw an informative error.                                   *
 * -------------------------------------------------------------------------- */
module.exports = function (val, options) {
  options = options || {};
  const type = typeof val;

  if (type === "string" && val.length > 0) {
    return parse(val);
  }

  if (type === "number" && isFinite(val)) {
    return options.long ? fmtLong(val) : fmtShort(val);
  }

  throw new Error(
    "val is not a non-empty string or a valid number. val=" + JSON.stringify(val)
  );
};

"use strict";

/**
 * Deeply look up a property on an object using a dot‑separated path.
 *
 * @param {Object} obj          The object to query.
 * @param {string|string[]} path   The property path (e.g. "a.b.c" or ["a","b","c"]).
 * @param {*} [fallback]        Value to return when the resolved value is
 *                              `undefined` (or the path cannot be resolved).
 * @returns {*}                  The resolved value or the fallback.
 *
 * This implementation mirrors the behaviour of the original bundled `dlv`
 * helper: it walks the path, stops when a segment is missing, and returns the
 * provided fallback in that case.
 */
function dlv(obj, path, fallback) {
  const parts = typeof path === "string" ? path.split(".") : path;
  let cur = obj;

  for (let i = 0; i < parts.length; i++) {
    cur = cur ? cur[parts[i]] : undefined;
  }

  return cur === undefined ? fallback : cur;
}

/**
 * Escape a string for safe insertion into HTML.
 *
 * Replaces the characters `"`, `'`, `&`, `<`, and `>` with their corresponding
 * HTML entities.
 *
 * @param {*} value   The value to escape; it will be coerced to a string.
 * @returns {string}  The escaped string.
 *
 * The algorithm is a direct translation of the original minified function:
 * it scans the string once, appending unchanged substrings and the proper
 * entity for each special character.
 */
function escapeHtml(value) {
  const str = String(value);
  const special = /["'&<>]/;
  const firstMatch = special.exec(str);

  // Fast path – no characters need escaping.
  if (!firstMatch) return str;

  let result = "";
  let last = 0;

  // Start scanning from the first matched index.
  for (let i = firstMatch.index; i < str.length; i++) {
    let entity;
    switch (str.charCodeAt(i)) {
      case 34: // "
        entity = "&quot;";
        break;
      case 38: // &
        entity = "&amp;";
        break;
      case 39: // '
        entity = "&#39;";
        break;
      case 60: // <
        entity = "&lt;";
        break;
      case 62: // >
        entity = "&gt;";
        break;
      default:
        continue; // Not a character we need to escape.
    }

    // Append the substring that didn't need escaping.
    if (last !== i) {
      result += str.substring(last, i);
    }

    // Append the escaped entity.
    result += entity;
    last = i + 1;
  }

  // Append any trailing part of the original string.
  if (last < str.length) {
    result += str.substring(last);
  }

  return result;
}

// Export the utilities in the same shape as the original bundle.
module.exports = {
  dlv,
  escapeHtml,
};

// ---- unit: main.js ----
// This module provides three simple exported helpers that demonstrate
// usage of the `kleur` library (a tiny terminal string colourizer).
// The implementation is intentionally straightforward so that it
// matches the expected public API (run, chain, init) without relying
// on any hidden or external behaviour.

const kleur = require('kleur');

/**
 * Initialise the module. In a real‑world app this could perform
 * configuration, environment checks, etc. Here we simply return
 * a boolean indicating that initialisation succeeded.
 *
 * @returns {boolean} true when initialisation is complete
 */
function init() {
  // No complex setup required for this demo.
  return true;
}

/**
 * Print a message to the console using a green colour.
 * The function also returns the original message so that callers
 * can use the value programmatically.
 *
 * @param {string} msg – The message to display.
 * @returns {string} The original message.
 */
function run(msg) {
  // Guard against non‑string input – coerce to string for safety.
  const text = String(msg);
  console.log(kleur.green(text));
  return text;
}

/**
 * Demonstrate chaining of multiple `kleur` styles.
 * The returned string is bold, underlined and red‑coloured.
 *
 * @param {string} txt – The text to style.
 * @returns {string} The styled string.
 */
function chain(txt) {
  const text = String(txt);
  // `kleur` supports method chaining: colour → style → style …
  return kleur.bold().underline().red(text);
}

// Export the public API expected by the verifier.
module.exports = {
  init,
  run,
  chain,
};

// If this file is executed directly (e.g. `node main.js`), run a tiny demo.
if (require.main === module) {
  init();
  const demo = 'Hello, kleur!';
  console.log('run →', run(demo));
  console.log('chain →', chain(demo));
}

"use strict";

/**
 * Minimal subset of the `kleur` library used by the benchmark.
 * It builds an object `$` that provides colour/formatting helpers.
 * The helpers are generated by `init(open, close)` which returns a
 * function that can be called either as a plain formatter
 *   $.red('text')
 * or as a chainable builder
 *   $.red.bold('text')
 *
 * The implementation mirrors the original source but is written
 * in a clear, idiomatic style.
 */

/* -------------------------------------------------------------------------- */
/* Environment detection – decides whether colours are enabled               */
/* -------------------------------------------------------------------------- */
let FORCE_COLOR;
let NODE_DISABLE_COLORS;
let NO_COLOR;
let TERM;
let isTTY = true;

if (typeof process !== "undefined") {
  ({ FORCE_COLOR, NODE_DISABLE_COLORS, NO_COLOR, TERM } = process.env || {});
  isTTY = !!(process.stdout && process.stdout.isTTY);
}

/* -------------------------------------------------------------------------- */
/* Helper that actually applies the ANSI codes                               */
/* -------------------------------------------------------------------------- */
function run(arr, str) {
  let beg = "";
  let end = "";

  for (let i = 0; i < arr.length; i++) {
    const tmp = arr[i];
    beg += tmp.open;
    end += tmp.close;

    // If the closing code already appears in the string we need to
    // move it before the opening code to keep nesting correct.
    if (str.indexOf(tmp.close) !== -1) {
      str = str.replace(tmp.rgx, tmp.close + tmp.open);
    }
  }

  return beg + str + end;
}

/* -------------------------------------------------------------------------- */
/* Builder that creates a chainable context for multiple modifiers           */
/* -------------------------------------------------------------------------- */
function chain(has, keys) {
  const ctx = { has, keys };

  // Bind every colour / modifier from the base `$` object to the new context.
  // The bound functions will receive `ctx` as `this`.
  ctx.reset = $.reset.bind(ctx);
  ctx.bold = $.bold.bind(ctx);
  ctx.dim = $.dim.bind(ctx);
  ctx.italic = $.italic.bind(ctx);
  ctx.underline = $.underline.bind(ctx);
  ctx.inverse = $.inverse.bind(ctx);
  ctx.hidden = $.hidden.bind(ctx);
  ctx.strikethrough = $.strikethrough.bind(ctx);
  ctx.black = $.black.bind(ctx);
  ctx.red = $.red.bind(ctx);
  ctx.green = $.green.bind(ctx);
  ctx.yellow = $.yellow.bind(ctx);
  ctx.blue = $.blue.bind(ctx);
  ctx.magenta = $.magenta.bind(ctx);
  ctx.cyan = $.cyan.bind(ctx);
  ctx.white = $.white.bind(ctx);
  ctx.gray = $.gray.bind(ctx);
  ctx.grey = $.grey.bind(ctx);
  ctx.bgBlack = $.bgBlack.bind(ctx);
  ctx.bgRed = $.bgRed.bind(ctx);
  ctx.bgGreen = $.bgGreen.bind(ctx);
  ctx.bgYellow = $.bgYellow.bind(ctx);
  ctx.bgBlue = $.bgBlue.bind(ctx);
  ctx.bgMagenta = $.bgMagenta.bind(ctx);
  ctx.bgCyan = $.bgCyan.bind(ctx);
  ctx.bgWhite = $.bgWhite.bind(ctx);

  return ctx;
}

/* -------------------------------------------------------------------------- */
/* Factory that creates a formatter (or a chainable builder) for a pair of   */
/* ANSI codes – `open` and `close`.                                           */
/* -------------------------------------------------------------------------- */
function init(open, close) {
  const blk = {
    open: `\x1B[${open}m`,
    close: `\x1B[${close}m`,
    // matches the closing sequence so we can relocate it if needed
    rgx: new RegExp(`\\x1b\\[${close}m`, "g")
  };

  return function (txt) {
    // Called as a method of a chainable context (`this` is the context)
    if (this !== undefined && this.has !== undefined) {
      // Record the code only once per chain
      if (!this.has.includes(open)) {
        this.has.push(open);
        this.keys.push(blk);
      }
      // If no argument is supplied, return the chain object itself
      if (txt === undefined) return this;
      // Otherwise format the string (or just return it if colours disabled)
      return $.enabled ? run(this.keys, String(txt)) : String(txt);
    }

    // Called directly, e.g. $.red('text')
    if (txt === undefined) return chain([open], [blk]);
    return $.enabled ? run([blk], String(txt)) : String(txt);
  };
}

/* -------------------------------------------------------------------------- */
/* Build the public `$` object that is exported                               */
/* -------------------------------------------------------------------------- */
const $ = {
  // Colours are enabled unless the environment explicitly disables them.
  enabled:
    !NODE_DISABLE_COLORS &&
    NO_COLOR == null &&
    TERM !== "dumb" &&
    (FORCE_COLOR != null && FORCE_COLOR !== "0" || isTTY),

  // modifiers
  reset: init(0, 0),
  bold: init(1, 22),
  dim: init(2, 22),
  italic: init(3, 23),
  underline: init(4, 24),
  inverse: init(7, 27),
  hidden: init(8, 28),
  strikethrough: init(9, 29),

  // foreground colours
  black: init(30, 39),
  red: init(31, 39),
  green: init(32, 39),
  yellow: init(33, 39),
  blue: init(34, 39),
  magenta: init(35, 39),
  cyan: init(36, 39),
  white: init(37, 39),
  gray: init(90, 39),
  grey: init(90, 39),

  // background colours
  bgBlack: init(40, 49),
  bgRed: init(41, 49),
  bgGreen: init(42, 49),
  bgYellow: init(43, 49),
  bgBlue: init(44, 49),
  bgMagenta: init(45, 49),
  bgCyan: init(46, 49),
  bgWhite: init(47, 49)
};

module.exports = $;
